<script>
// 辅助函数 (无需更改)
function SafeGetValue(obj, path, defaultValue = "N/A") {
    let keys = Array.isArray(path) ? path : path.split('.');
    let current = obj;
    for (let i = 0; i < keys.length; i++) {
        if (current === undefined || current === null) return defaultValue;

        const key = keys[i];
        if (Array.isArray(current)) {
            const index = parseInt(key, 10);
            if (isNaN(index) || index < 0 || index >= current.length) return defaultValue;
            current = current[index];
        } else if (typeof current === 'object' && current.hasOwnProperty(key)) {
            current = current[key];
        } else {
            return defaultValue;
        }
    }
    return (current === undefined || current === null) ? defaultValue : current;
}


const rarityLookup = {
    '神话': { badge: 'UR', css: 'UR' }, 'UR': { badge: 'UR', css: 'UR' },
    '传说': { badge: 'SSR', css: 'SSR' }, 'SSR': { badge: 'SSR', css: 'SSR' },
    '超稀有': { badge: 'SR', css: 'SR' }, 'SR': { badge: 'SR', css: 'SR' },
    '稀有': { badge: 'R', css: 'R' }, 'R': { badge: 'R', css: 'R' },
    '普通': { badge: 'N', css: 'N' }, 'N': { badge: 'N', css: 'N' }
};

function renderDisplayPool(containerId, dataArray, titleIfEmpty) {
    const container = document.getElementById(containerId);
    if (!container) return;
    container.innerHTML = '';

    if (!dataArray || !Array.isArray(dataArray) || dataArray.length === 0) {
        container.innerHTML = `<div class="pool-item rarity-N"><div class="item-content"><p>${titleIfEmpty}</p></div></div>`;
        return;
    }

    let listHTML = '';
    dataArray.forEach(item => {
        if (typeof item === 'object' && item.name) {
             const rarityKey = String(item.rarity || 'N').trim().split(' ')[0];
             const rarityInfo = rarityLookup[rarityKey] || { badge: '?', css: 'N' };
             listHTML += `
                <div class="pool-item rarity-${rarityInfo.css}">
                    <div class="item-content">
                        <strong>${item.name}</strong>
                        <p>${item.description || ''}</p>
                    </div>
                    <div class="rarity-badge">${rarityInfo.badge}</div>
                </div>
            `;
        }
    });
    container.innerHTML = listHTML;
}

function renderChoicePool(containerId, dataArray, poolName, titleIfEmpty) {
    const container = document.getElementById(containerId);
    if (!container) return;
    container.innerHTML = '';

    if (!dataArray || !Array.isArray(dataArray) || dataArray.length === 0) {
        container.innerHTML = `<div class="pool-item rarity-N"><div class="item-content"><p>${titleIfEmpty}</p></div></div>`;
        return;
    }

    let listHTML = '';
    dataArray.forEach(item => {
        if (typeof item === 'object' && item.name) {
            const rarityKey = String(item.rarity || 'N').trim().split(' ')[0];
            const rarityInfo = rarityLookup[rarityKey] || { badge: '?', css: 'N' };
            // 修正：确保 value 中的 JSON 字符串是有效的，特别是处理单引号
            const itemJson = JSON.stringify(item).replace(/'/g, "\\'");

            listHTML += `
                <label class="pool-item-label">
                    <input type="radio" name="${poolName}-choice" value='${itemJson}'>
                    <div class="pool-item rarity-${rarityInfo.css}">
                        <div class="item-content">
                            <strong>${item.name}</strong>
                            <p>${item.description || ''}</p>
                        </div>
                        <div class="rarity-badge">${rarityInfo.badge}</div>
                    </div>
                </label>
            `;
        }
    });
    container.innerHTML = listHTML;
}

function updateStatDisplay(elementId, value) {
    const element = document.getElementById(elementId);
    if (element) {
        const finalValue = Array.isArray(value) ? value[0] : value;
        element.innerText = String(finalValue); // 确保是字符串
    }
}

async function initDisplay() {
    try {
        const messages = getChatMessages('0-{{lastMessageId}}');
        if (!messages || messages.length === 0) {
             console.log("No messages found or empty chat.");
             return;
        }

        let characterData = null;
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].data && messages[i].data.stat_data) {
                characterData = messages[i].data.stat_data;
                break;
            }
        }

        if (!characterData) {
            console.log("stat_data not found in any message.");
            return;
        }

        const characterKey = "主神空间";

        if (characterData.hasOwnProperty(characterKey)) {
            // --- 核心数据更新 ---
            updateStatDisplay('godspace-level', SafeGetValue(characterData, `${characterKey}.核心数据.等级`, 'N/A'));
            const bonusValueRaw = SafeGetValue(characterData, `${characterKey}.当前世界配置.稀有度概率加成`, [0]);
            const bonusPercentage = (parseFloat(Array.isArray(bonusValueRaw) ? bonusValueRaw[0] : bonusValueRaw) * 100).toFixed(2);
            updateStatDisplay('godspace-rarity-bonus', `${bonusPercentage}%`);

            // --- 世界和能力池更新 ---
            updateStatDisplay('godspace-current-world', SafeGetValue(characterData, `${characterKey}.世界穿梭.当前世界`, '[尚未选择]'));

            const permanentAbilitiesData = SafeGetValue(characterData, `${characterKey}.永久能力池`, [[], '']);
            // 提取数组并渲染
            renderDisplayPool('permanent-abilities-list', permanentAbilitiesData[0], '永久能力池为空');

            const identityPoolData = SafeGetValue(characterData, `${characterKey}.当前世界配置.身份抽取池`, [[], '']);
            // 【修正】直接使用 identityPoolData[0]，它已经是数组了
            renderChoicePool('identity-pool-list', identityPoolData[0], 'identity', '身份池为空');

            const abilityPoolData = SafeGetValue(characterData, `${characterKey}.当前世界配置.能力抽取池`, [[], '']);
            // 【修正】直接使用 abilityPoolData[0]，它已经是数组了
            renderChoicePool('ability-pool-list', abilityPoolData[0], 'ability', '能力池为空');

        } else {
             // 处理数据缺失的情况
             updateStatDisplay('godspace-level', '数据缺失');
             updateStatDisplay('godspace-rarity-bonus', '数据缺失');
             updateStatDisplay('godspace-current-world', '数据缺失');
             renderDisplayPool('permanent-abilities-list', [], '数据缺失');
             renderChoicePool('identity-pool-list', [], 'identity', '数据缺失');
             renderChoicePool('ability-pool-list', [], 'ability', '数据缺失');
        }
    } catch (error) {
        document.getElementById('status-card').innerHTML = `<p style='color:red; padding:20px;'>状态栏加载出错: ${error.message}. 请确保在SillyTavern环境内使用此页面。</p>`;
    }
}

// =================================================================
// 【唯一的修改在这里】
// =================================================================
async function handleFormSubmit(event) {
    event.preventDefault();
    const selectedIdentityRadio = document.querySelector('input[name="identity-choice"]:checked');
    const selectedAbilityRadio = document.querySelector('input[name="ability-choice"]:checked');
    const selectedAge = document.querySelector('input[name="age-appearance"]:checked')?.value || '未选择';
    const penisLength = document.getElementById('penis-length').value;
    const customDetails = document.getElementById('custom-details').value;

    // 从显示区域获取当前世界名称
    const currentWorldName = document.getElementById('godspace-current-world').innerText;

    let identityText = '未选择';
    if (selectedIdentityRadio) {
        const identityData = JSON.parse(selectedIdentityRadio.value);
        identityText = `${identityData.name} (稀有度: ${identityData.rarity})`;
    }

    let abilityText = '未选择';
    if (selectedAbilityRadio) {
        const abilityData = JSON.parse(selectedAbilityRadio.value);
        abilityText = `${abilityData.name} (稀有度: ${abilityData.rarity})`;
    }

    let summary = `【创角信息确认】\n`;

    // 【新增逻辑】检查当前世界是否有值，如果有，则添加到摘要的第一行
    if (currentWorldName && currentWorldName.trim() !== '' && currentWorldName !== '[尚未选择]') {
        summary += `我选择的世界是：${currentWorldName}\n`;
    }

    // 添加其他信息
    summary += `选择的身份：${identityText}\n`;
    summary += `选择的临时能力：${abilityText}\n`;

    if (customDetails.trim()) {
        summary += `自定义详细设定：\n${customDetails}`;
    } else {
        summary += `外貌年龄：${selectedAge}\n`;
        if (penisLength) {
            summary += `鸡巴长度：${penisLength}cm`;
        } else {
            summary += `鸡巴长度：未设定`;
        }
    }

    try {
        if (typeof triggerSlash === 'function') {
            const command = `/send "${summary}" | /trigger`;
            await triggerSlash(command);
        } else {
            alert("错误：无法找到 triggerSlash 函数。请确保在正确的SillyTavern插件环境中使用。");
        }
    } catch (error) {
        console.error("提交创角信息时出错:", error);
        alert(`提交失败: ${error.message}`);
    }
}
// =================================================================
// 【修改结束】
// =================================================================


document.addEventListener('DOMContentLoaded', () => {
    initDisplay();
    const form = document.getElementById('creation-form');
    if(form) {
        form.addEventListener('submit', handleFormSubmit);
    }
});
</script>
</body>
</html>
