<script>
    document.addEventListener('DOMContentLoaded', () => {
        const form = document.getElementById('world-selection-form');
        const customInput = document.getElementById('custom-world-input');
        const presetRadios = document.querySelectorAll('input[name="world-preset"]');

        customInput.addEventListener('input', () => {
            if (customInput.value.trim() !== '') {
                presetRadios.forEach(radio => radio.checked = false);
            }
        });

        presetRadios.forEach(radio => {
            radio.addEventListener('change', () => {
                if (radio.checked) {
                    customInput.value = '';
                }
            });
        });

        form.addEventListener('submit', async (event) => {
            event.preventDefault();
            const customWorld = customInput.value.trim();
            const selectedPreset = document.querySelector('input[name="world-preset"]:checked');
            let finalChoice = '';

            if (customWorld) {
                finalChoice = customWorld;
            } else if (selectedPreset) {
                finalChoice = selectedPreset.value;
            }

            if (!finalChoice) {
                alert('请选择一个世界或输入自定义世界！');
                return;
            }

            const message = `我选择的世界是：${finalChoice}。进入主神空间......抽取该身份池...抽取该世界能力池。`;

            try {
                if (typeof triggerSlash === 'function') {
                    const command = `/send "${message}" | /trigger`;
                    await triggerSlash(command);
                } else {
                    console.error('错误：triggerSlash 函数未定义。此页面必须在支持该功能的SillyTavern插件环境中使用。');
                    alert('提交失败：无法连接到酒馆环境。');
                }
            } catch (error) {
                console.error('提交世界选择时出错:', error);
                alert(`提交失败: ${error.message}`);
            }
        });
    });
</script>
