            --rarity-n-bg: linear-gradient(135deg, #546e7a, #78909c);
            --rarity-n-glow: #b0bec5;
        }

        @keyframes move-bg {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }

        body {
            font-family: 'Noto Sans SC', 'Helvetica Neue', sans-serif;
            color: var(--text-primary);
            margin: 0;
            padding: 40px 20px; /* 增加顶部间距 */
            /* 动态星云背景 */
            background: linear-gradient(-45deg, #0c0a18, #2c1a4c, #1a2c4c, #0c0a18);
            background-size: 400% 400%;
            animation: move-bg 25s ease-in-out infinite;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        /* 标题更换并美化 */
        .main-title {
            font-size: 2.5em;
            font-weight: 700;
            color: var(--text-primary);
            letter-spacing: 5px; /* 增加字间距，更显大气 */
            margin-bottom: 40px;
            text-shadow: 0 0 10px var(--accent-gold), 0 0 20px var(--accent-gold);
        }

        /* 卡片采用磨砂玻璃效果 */
        .status-card {
            width: 100%;
            max-width: 800px;
            background: var(--card-bg);
            border-radius: 16px;
            overflow: hidden;
            padding: 24px 32px;
            margin-bottom: 24px;
            backdrop-filter: blur(10px) saturate(120%);
            -webkit-backdrop-filter: blur(10px) saturate(120%);
            position: relative;
            border: 1px solid transparent; /* 占位 */
        }

        /* 流光边框 */
        .status-card::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            border-radius: 16px;
            padding: 1px;
            background: linear-gradient(135deg, rgba(255, 215, 0, 0.4), rgba(46, 204, 255, 0.3));
            -webkit-mask: 
                linear-gradient(#fff 0 0) content-box, 
                linear-gradient(#fff 0 0);
            -webkit-mask-composite: destination-out;
            mask-composite: exclude;
            z-index: -1;
        }

        .section { margin-bottom: 32px; }
        .section:last-child { margin-bottom: 0; }

        /* 分区标题 - 居中，金色分割线 */
        .section-header {
            font-weight: 500;
            font-size: 1.2em;
