            box-shadow: 0 0 15px rgba(255, 215, 0, 0.2);
        }

        .item-content strong {
            font-weight: 700;
            font-size: 1.1em;
            color: var(--text-primary);
            margin-bottom: 8px;
            display: block;
        }
        .item-content p {
            font-size: 0.9em;
            color: var(--text-secondary);
            margin: 0;
            line-height: 1.6;
        }

        /* 稀有度徽章 - 仙丹/宝玉风格 */
        .rarity-badge {
            flex-shrink: 0;
            min-width: 60px; /* 保证宽度 */
            height: 28px;
            padding: 0 12px;
            display: flex;
            justify-content: center;
            align-items: center;
            border-radius: 99px; /* 胶囊形状 */
            font-weight: 700;
            font-size: 0.9em;
            border: none;
        }
        .rarity-UR .rarity-badge { background: var(--rarity-ur-bg); color: #fff; text-shadow: 0 0 5px var(--rarity-ur-glow); }
        .rarity-SSR .rarity-badge { background: var(--rarity-ssr-bg); color: #263238; text-shadow: 0 0 5px var(--rarity-ssr-glow); }
        .rarity-SR .rarity-badge { background: var(--rarity-sr-bg); color: #fff; text-shadow: 0 0 5px var(--rarity-sr-glow); }
        .rarity-R .rarity-badge { background: var(--rarity-r-bg); color: #fff; text-shadow: 0 0 5px var(--rarity-r-glow); }
        .rarity-N .rarity-badge { background: var(--rarity-n-bg); color: #fff; text-shadow: 0 0 5px var(--rarity-n-glow); }

        /* --- 表单样式美化 --- */
        #creation-form { width: 100%; max-width: 800px; }
        .form-group { margin-bottom: 28px; }
        .form-group > label { /* 直接的label，非radio */
            display: block;
            margin-bottom: 12px;
            font-weight: 500;
            color: var(--text-secondary);
            text-align: center;
        }
        .radio-group { display: flex; gap: 16px; flex-wrap: wrap; justify-content: center; }
        .radio-group label {
            background: rgba(30, 28, 50, 0.6);
            padding: 10px 24px;
            border-radius: 99px;
            border: 1px solid var(--border-color);
