        }
        .submit-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(255, 215, 0, 0.4);
        }

        /* 可选择池子 - 选中时发光 */
        .choice-pool .pool-item-label { display: block; cursor: pointer; }
        .choice-pool .pool-item-label input[type="radio"] { display: none; }
        .choice-pool .pool-item-label input[type="radio"]:checked + .pool-item {
            border-color: var(--accent-gold);
            box-shadow: 0 0 20px rgba(255, 215, 0, 0.5);
        }
    </style>
</head>
<body>
    <!-- 标题已更改 -->
    <h1 class="main-title">主神空间</h1>

    <div class="status-card" id="status-card">
        <div class="section">
            <div class="section-header">核心数据</div>
            <div class="core-stats-grid">
                <div class="stat-box">
                    <span class="property-name">等级</span>
