{
  "sex_scene_writing_guidelines": {
    "scene_setting": {
      "title": "场景与环境描写规范",
      "guidelines": [
        {
          "point": "环境烘托",
          "description": "通过对环境的细节描写（如'暖色的灯光'、'黑漆漆的一楼'）来构建私密、暧昧的氛围，为接下来的情节做铺垫。"
        },
        {
          "point": "情境合理化",
          "description": "为性行为设置一个非纯粹欲望驱动的框架，如'母妻骑术训练'、'提升持久力'。这使得角色的互动在故事逻辑中显得更为自然和必要，而非单纯的淫乱。"
        },
        {
          "point": "场景切换",
          "description": "通过场景的变换（从'花园训练场'到'妈妈的卧室'）来展现关系和互动模式的演进，增加情节的层次感。"
        }
      ]
    },
    "character_portrayal": {
      "title": "角色描绘规范",
      "guidelines": [
        {
          "point": "身体外貌（静态）",
          "description": "细致刻画角色的身体特征，使用直接且富有感官冲击力的词汇。例如：'白嫩的巨大乳房'、'G杯大奶'、'雪白圆润的大屁股'、'修长肉感的大长腿'、'粉色的嫩穴'。"
        },
        {
          "point": "服装与状态",
          "description": "重点描写服装的材质、款式及其在互动中的状态，以增强视觉刺激。例如：'标准的骑母套装'、'黑色花纹裤袜'、'10cm的黑色细高跟鞋'、'半透明的黑色蕾丝睡衣'、'裤袜被拉到了两条大腿上'。"
        },
        {
          "point": "性器官特写",
          "description": "对性器官进行具体、客观的特写描写，包括尺寸、颜色、形态和状态。例如：'深紫色龟头足有鸡蛋大小'、'粗长的深红色棒身'、'小穴像一张小嘴一样，变得鲜红的唇瓣'。"
        },
        {
          "point": "身高体格差距（小马拉大车）",
          "description": "通过对比来强化体型差异带来的视觉和心理冲击。例如：'妈妈高挑的身材显得更加高大，同时也让我显得更加矮小'；动作上体现为男方双手抓握女方'肥厚圆润的屁股'，女方身体能完全承受甚至包裹男方的动作。"
        }
      ]
    },
    "interaction_and_action": {
      "title": "互动与动作描写规范",
      "guidelines": [
        {
          "point": "动作描写",
          "description": "使用精准且有力的动词来描述性行为过程，如'撞击'、'耸动'、'插入'、'抽插'、'顶'。强调动作的节奏和力度，如'快速前后耸动'、'猛烈的撞击'。"
        },
        {
          "point": "物理反馈",
          "description": "生动描写动作带来的身体反应，增强真实感。例如：'臀肉被我撞的一阵抖动'、'屁股被撞得臀波阵阵'、'胸前那两颗巨大的 G杯大奶也随之一阵乳波奶浪'。"
        },
        {
          "point": "感官体验（触觉）",
