        },
        {
          "point": "液体描写",
          "description": "客观且详细地描写体液的产生、流动和形态。例如：'黏滑汁液慢慢溢出，像蜂蜜水一样'、'流出了浓白色的液体'、'精液...从妈妈的小穴里流出来，粘成一条线'。"
        }
      ]
    },
    "dialogue_and_sound": {
      "title": "对话与声音描写规范",
      "guidelines": [
        {
          "point": "淫叫格式",
