        },
        {
          "point": "对话内容",
          "description": "对话应推动情节并塑造角色性格。例如，妈妈以'训练'为名义解释性行为，展现了她的主导地位和试图维持母亲形象的努力。对话内容可以包含教学、催促、询问和解释。"
        },
        {
          "point": "淫语与称呼",
          "description": "根据角色关系和场景氛围，灵活使用不同程度的性相关词汇。从'鸡鸡'到'肉棒'、'鸡巴'，从'下面的洞'到'小穴'、'蜜穴'，词汇的演变反映了角色认知的变化和关系的深入。"
        },
        {
          "point": "复合声音描写",
          "description": "将多种声音交织在一起，创造沉浸式的听觉体验。例如：'高跟鞋的声音（哒哒哒）'、'肉体撞击声（啪啪啪）'和'液体交合声（啪叽啪叽）'三种声音充斥在房间里。"
        }
      ]
    },
    "physiological_response": {
      "title": "生理反应描写规范",
      "guidelines": [
        {
          "point": "兴奋迹象",
          "description": "详细描写角色在兴奋状态下的生理变化。例如：'肉棒变硬膨胀'、'妈妈下面又开始湿漉漉的了'、'小穴收缩的频率也越来越快了'。"
        },
        {
          "point": "高潮与射精",
          "description": "客观地描写高潮时的感受和射精过程。例如：'一股电流从下面传来'、'两颗大蛋蛋的收缩，将一股一股的东西射在了妈妈的小穴里'。女方的反应是'身体也微微颤抖了一下'，保持温和克制。"
        },
        {
          "point": "事后状态",
          "description": "描写高潮后的身体状态，包括疲惫感和生理现象。例如：'疲惫地骑在妈妈的屁股上，大口大口地喘气'、'妈妈的下面就流出了浓白色的液体'、'肉棒上沾满了妈妈的水，还有一些浑浊的白色液体'。"
        }
      ]
    },
    "narrative_rules": {
      "title": "整体叙事准则",
      "guidelines": [
        {
          "point": "积极情绪导向",
          "description": "聚焦于角色感受到的'舒服'、'满足'、'舒爽'等积极体验，弱化或避免描写痛苦、抗拒等负面情绪，确保整体基调的愉悦性。"
        },
        {
          "point": "角色主动性",
          "description": "NPC（妈妈）应表现出强烈的主动性，她不仅是接受者，更是训练的主导者、规则的制定者和情节的推动者。"
        },
        {
          "point": "避免抽象比喻",
          "description": "坚持使用白描手法，通过具体的动作、声音、生理反应来直接呈现场景，避免使用'像……一样'、'如同……'等比喻句式来形容感受。"
        },
        {
          "point": "逻辑自洽",
          "description": "所有互动和描写都必须在设定的框架内（如'母妻骑术'）保持逻辑自洽，并符合基本的人体物理和生理规律。"
        }
      ]
    }
  }
}

