以下是武侠文风的参考案例，严格遵守：
{
  "style_guide_title": "古风武侠官能融合风格创作纲要",
  "perspective_and_narrative": {
    "primary_perspective": "第三人称限定视角",
    "description": "叙事严格遵循核心角色的感官体验，让读者与角色同步感知世界。严禁上帝视角，角色仅知晓其通过五感直接获取的信息，以确保认知隔离，增强沉浸感。",
    "narrative_focus": "致力于呈现直接、原始的感官冲击。所有细节，尤其是五感（视觉、触觉、嗅觉、味觉、听觉）相关的描写，必须充分、具体、生动。语言表达灵活多变，避免行文模式化。"
  },
  "character_portrayal": {
    "appearance_and_clothing": {
      "technique": "采用白描与细节堆砌，摒弃笼统形容。外貌描写需聚焦于'凤眼'、'朱唇'、'玉颈'、'皓腕'等局部特写，结合'媚眼如丝'、'巧笑倩兮'等神态，展现人物的鲜活魅力。",
      "skin_and_body_description": "肤色莹白，肌骨如凝脂，带有温润光泽。体态可丰腴或玲珑，曲线柔美，突出酥胸、纤腰、嫩足等部位。细节刻画入微，如足踝、指尖的滑腻、圆润，甚至可见皮下青络。",
      "clothing_details": "服装描写注重材质（如薄纱、罗绸、云锦）、款式（如对襟襦裙、肚兜、亵裤）及状态。通过'衣衫半解'、'罗裳凌乱'、'薄纱紧贴'等状态来烘托人物心境、凸显身体曲线，其穿脱过程需详细描绘，层层递进。"
    },
    "dialogue_and_interaction": {
      "style": "半文半白，语言风格需符合人物身份、性格及当前情境。端庄角色在私密场合的粗俗放浪言语能形成强烈反差，增强戏剧张力。",
      "address_terms": "称呼需根据关系演变灵活切换。初期可使用'师傅'、'弟子'、'夫人'、'先生'等正式称谓；随着关系亲密，可转为'蓉儿'、'过儿'、'郎君'等昵称；在情欲高涨时，更可使用'冤家'、'心肝儿'、'小骚货'等挑逗性称呼。",
      "language_features": "对话多用反问、嗔怪、娇叱等语气，并伴随'白了他一眼'、'抚着他的头发'等细微动作传递潜台词。严禁使用省略号（'...'或'……'）表达迟疑或喘息，必须以完整句子、清晰标点或直接的文字描述（如'他声音沙哑'、'她娇喘一声'）替代。"
    }
  },
  "environment_and_atmosphere": {
    "weather_and_time": "天气（风雨、月色、夕阳）与时间需服务于情节氛围，用以烘托角色情绪或预示事件转折。如以'风雨交加'制造危机，以'月下林间'营造私密暧昧。",
    "setting_details": "环境描写需细致且富有暗示性。通过对场景（如巖洞、香闺、水潭）及器物（如乾草床铺、摇曳红烛、袅袅熏香、紫檀足盆）的刻画，增加真实感，丰富场景层次，并暗示情欲氛围。"
  },
  "erotic_scene_construction": {
    "core_principle": "温和官能主义。聚焦于生理驱动的感官体验，将性爱描绘为美好的情感表达，而非激烈冲突或极端情节。摒弃暴力、支配元素，强调双方的和谐与愉悦。",
    "sensory_details": {
      "visual": "细致刻画性器官在兴奋时的具体形态、色泽、纹理、尺寸、硬度、湿润度（如'色呈紫青'、'独目怒张'、'淫水淋漓'），以及身体的生理反应，如皮肤潮红、肌肉紧绷、汗珠滑落。红（乳头、吻痕）与白（肌肤）的色彩对比尤为重要。",
      "auditory": "听觉描写需直接、清晰。使用明确的拟声词（如水声'啧啧'、'咕叽'，肉体撞击声'啪啪'）和直白的呻吟、喘息及淫语，构成强烈的听觉刺激。",
      "tactile": "着重描写皮肤与器官的触感，如'绵软滑顺'、'火烫粗壮'、'湿滑紧致'，以及体液的'温热黏稠'。对足心、趾肚等敏感部位的触感进行微观放大描写。",
      "olfactory_and_gustatory": "通过描写体香、麝香、乳香以及爱液的味道（如'甘甜'或'微腥'），从嗅觉和味觉维度增强沉浸感。"
    },
    "actions_and_process": {
      "anatomical_realism": "所有互动必须严格遵守人体生理结构及物理限制。例如，后入式无法完成面对面的动作；被占用的器官无法同时进行其他活动。",
      "progressive_escalation": "性行为的描写应循序渐进，从试探性的爱抚（吻颈、磨蹭）到核心的交合，层层递进，逐步升温。详细描绘插入过程的感受与最终的契合感（如'噗嗤一声，尽根没入'）。",
      "movement_and_rhythm": "动作描写具体，如'大起大落的狠插'、'细柳轻摇般的研磨'，节奏应富于变化，以匹配情欲的涨落。",
      "climax_and_aftermath": "高潮描写需克制，强调双方和谐同步的'酣适'感。角色在高潮时应保持镇定，避免尖叫、痉挛等过度反应，事后不会丧失行动能力或昏厥。高潮后需描写余韵和温存，如疲惫的满足感、身体上的痕迹（吻痕、体液），作为情节的自然延伸。",
      "no_harm_principle": "亲吻通常不会导致嘴唇红肿，常规性爱不会让身体留下伤痕，确保互动的美好感受。",
      "satiety_principle": "为避免剧情停滞，角色在经历高潮或射精后，性欲将得到满足，不再主动索求，剧情应转向事后温存或其他发展。"
    },
    "anatomy_and_dirty_talk": {
      "naming_conventions": "性器称呼需根据角色性格、场景氛围灵活选用。可使用'话儿'、'妙处'、'肉棒'、'小穴'，或在特定情境下使用更粗俗的'鸡巴'、'大屌'、'骚屄'等，以增强真实感和表现力。",
      "dirty_talk_style": "淫语需与人物性格和关系转变相匹配，风格应直接、露骨，避免文艺修饰。角色的语言可从初期的压抑惊呼（如'过儿不要'）转变为主动的索求或评价（如'师傅，我要进去了'或'冤家，可要狠些才好'），体现其内心的变化。"
    }
  }
}

