{
  "仙侠风月描写总纲": {
    "version": "2.0-Fusion",
    "creator": "Anon",
    "description": "本总纲融合了多版本仙侠描写指南，旨在提供一个全面、系统且富有层次的创作框架。内容涵盖从宏观风格到微观细节的各个方面，力求在古典雅致与原始欲望之间取得平衡，实现极致的感官沉浸与情感共鸣。",
    "一、整体风格与基调": {
      "summary": "融合古典韵味、现代语感、神圣仪式感与世俗烟火气。核心在于营造强烈的感官冲击与意境，通过鲜明对比（如圣洁与淫靡、压抑与爆发）展现人物的内心挣扎与复杂人性。",
      "keywords": [
        "感官浸入",
        "具象化细节",
        "动静结合",
        "圣俗交织",
        "心理外显",
        "情欲张力",
        "节奏多变",
        "意境烘托"
      ]
    },
    "二、人物塑造": {
      "服装描写": {
        "focus": "材质、色彩、剪裁、纹饰、配饰及其与身体的互动，以此暗示人物身份、性格、心境与情欲状态。",
        "elements": {
          "材质与质感": {
            "仙气飘逸": ["云裳羽衣", "流仙裙", "鲛人泪纱", "天蚕丝锦", "薄纱", "罗绸"],
            "华贵庄重": ["锦缎", "白锦", "琉璃宝甲", "金丝绣纹"],
            "朴实/功能性": ["青衫", "臃肿棉袍", "狐裘领子"],
            "情趣暗示": ["湿透小肚兜", "紧窄白色小布", "蕾丝抹胸"]
          },
          "色彩与图案": {
            "清雅/仙家": ["月白", "青翠", "雪白"],
            "艳丽/情动": ["桃红", "大红", "紫黑"],
            "特殊纹饰": ["金色经文", "莲瓣", "阴阳八卦", "合欢花纹"]
          },
          "结构与穿戴效果": {
            "风格": ["广袖道袍", "层叠莲瓣", "镂空设计", "玉带环腰"],
            "效果": ["飘然若仙", "裹紧勒肉", "堪堪遮住", "罗裳半褪", "散作一团"]
          },
          "配饰": ["金色项圈", "璎珞", "黑檀佛珠", "金铃", "玉簪", "遍地金满绣高底睡鞋"]
        },
        "example_phrasing": "月白流仙裙薄如蝉翼，半透的纱幔下，雪腻的肌肤泛着莹润光泽，行动间霞光流转，似有星辰碎屑自裙摆洒落。而那桃红洒金的薄纱衫则半裹着酥胸，紧窄的蕾丝抹胸下，峰峦曲线若隐若现，无端撩人。"
      },
      "外貌描写": {
        "focus": "将超凡脱俗的‘仙气’与活色生香的‘肉感’结合，通过具体特征、动态表情和生理反应，立体化呈现人物。",
        "elements": {
          "整体气质": ["仙风道骨", "谪仙入尘", "高贵冷艳", "成熟丰韵", "清瘦坚韧", "病态破碎"],
          "面部与五官": {
            "眼睛": ["凤眸", "狐眸", "秋水双眸", "目若寒星"],
            "眉毛": ["远山眉", "黛眉（竖、平、团、展）"],
            "唇与齿": ["朱唇一点", "红艳香唇", "小虎牙"]
          },
          "身体特征": {
            "肌肤": ["肤若凝脂", "白皙如雪", "莹白如玉", "皮肉腻滑如酥"],
            "体态": ["丰乳肥臀", "吊钟巨乳", "爆硕肥臀", "水蛇软腰", "修长丰腴的双腿"],
            "细节": ["玉笋般的脚趾", "白里透粉的足尖", "踝骨纤细伶仃", "锁骨深窝"]
          },
          "生理反应与神态": {
            "情绪外显": ["香腮潮赤", "呼吸一滞", "娇羞", "眼波流转", "媚眼如丝"],
            "情动表现": ["身体颤栗", "足尖蜷收", "五官扭曲", "泪光盈盈", "瞳孔涣散"]
