          "听觉": "黏腻的水声（噗嗤、咕啾）；肉体撞击声（啪、噗）；喘息、呻吟、浪叫、淫语。",
          "触觉": "温热、湿滑、紧致、粗糙；器官的硬度、柔软度；肌肉的紧绷与松弛。",
          "嗅觉": "体香、麝香、淫靡的腥膻气味。",
          "动作": {
            "前戏": ["灵力探查", "指尖勾缠", "唇舌舔舐", "吸吮", "研磨"],
            "交合": ["顶开", "捅入", "抽插", "撞击", "扭摆", "吞吐", "深捣", "贯穿"]
          },
          "生理反应": "勃起充血、爱液分泌、肌肉紧绷、皮肤潮红、呼吸急促、身体轻颤。",
          "液体描绘": ["香涎", "淫水", "蜜汁", "精液", "白浊", "乳汁"]
        },
        "example_phrasing": "他握住那根粗如儿臂的肉棒，青筋虬结，顶端马眼正微微泌出清液。她双腿大开，湿漉漉的穴口翕张着，粉嫩的内唇早已翻出。他将龟头对准那泥泞的缝隙，只稍一用力，便“噗嗤”一声顶了进去。紧致湿热的穴肉立刻缠了上来，贪婪地裹紧、吸吮着这外来的侵入者。他开始不疾不徐地抽送，每一次拔出都带出亮晶晶的淫水，每一次顶入都发出沉闷的撞击声，激得她臀肉乱颤。"
      },
      "淫语浪言": {
        "focus": "作为情欲的催化剂和情感的直接表达，需符合人物性格从矜持到放浪的转变过程。",
        "示例": [
          "“嗯……好哥哥……你的大东西好烫……”",
          "“快……快顶死我……就要那里……”",
          "“小骚货，看我今天不把你干得潮吹……”",
          "“啊呀！好郎君！要了奴家的命了，你的鸡巴要把我的小穴捣烂了！”"
        ]
      },
      "高潮与余韵": {
        "focus": "高潮反应应温和而绵长，避免夸张的痉挛或昏厥。事后温存是情感交融的体现。",
        "高潮表现": "身体满足地轻微颤抖、满足的叹息、眼角溢出生理性的泪水、花穴一阵阵收缩。",
        "事后温存": "相拥而眠、低语、轻吻、抚摸、清理身体。"
      }
    },
    "六、语言技巧与修辞": {
      "手法": [
        {
          "名称": "感官白描",
          "说明": "摒弃“像……一样”的烂俗比喻，通过直接、客观的动作、表情、语言描写，呈现人物状态和感官体验。"
        },
        {
          "名称": "动态描写",
          "说明": "多使用富有张力的动词，营造强烈的动态感和力量感（如：剐蹭、研磨、驰骋、焚身）。"
        },
        {
          "名称": "节奏控制",
          "说明": "长短句结合，长句铺陈细节，短句突出爆发点，通过叙事节奏的变化增强感官刺激。"
        },
        {
          "名称": "意象化用",
          "说明": "将宗教、修行概念（如金刚杵、菩提心、乐空双运）进行情色化转译，制造神圣与淫靡的反差张力。"
        }
      ]
    }
  }
}

